--
-- Table structure for table `produce_manhour`
--

DROP TABLE IF EXISTS `produce_manhour`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `produce_manhour` (
  `name` varchar(128) NOT NULL COMMENT '零件名称',
  `model` varchar(64) DEFAULT NULL COMMENT '零件型号',
  `material` varchar(64) DEFAULT NULL COMMENT '材质',
  `unit` enum('g','m','p') NOT NULL COMMENT '计算单位：g=重量 m=长度 p=件',
  `unit_hour` bigint NOT NULL DEFAULT '0' COMMENT '单位工时ms',
  `blanking_ratio` int DEFAULT '0' COMMENT '下料工时比率',
  `welding_ratio` int DEFAULT '0' COMMENT '铆焊工时比率',
  `fitting_ratio` int DEFAULT '0' COMMENT '装配工时比率',
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `uuid` varchar(64) NOT NULL DEFAULT (uuid()) COMMENT 'UUID',
  `status` varchar(10) NOT NULL DEFAULT '0' COMMENT '状态 0=启用 1=停用',
  `description` text COMMENT '备注/描述',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_id` int DEFAULT NULL COMMENT '创建人ID',
  `updated_id` int DEFAULT NULL COMMENT '更新人ID',
  PRIMARY KEY (`id`),
  KEY `fk_bom_created_id` (`created_id`),
